from pathlib import Path
import json, hashlib
p = Path('products/services/sqlite-repair/bespoke-inbound/director-intake-field-readback.json')
raw = p.read_bytes()
source = json.loads(raw)
def strings(value):
    if isinstance(value, str):
        yield value
    elif isinstance(value, list):
        for item in value:
            yield from strings(item)
    elif isinstance(value, dict):
        for item in value.values():
            yield from strings(item)
case = {'setup_sql':'CREATE TABLE stock (sku TEXT, qty INTEGER); INSERT INTO stock VALUES (\'A\', 2), (\'B\', 0);','failing_sql':'SELECT sku FROM stock WHERE qty >= 0 ORDER BY sku;','expected_rows':[['A']],'qualification_question':'Could you send the private terms for diagnosing this fictional query?'}
import sqlite3
with sqlite3.connect(':memory:') as db:
    db.executescript(case['setup_sql'])
    actual = [list(row) for row in db.execute(case['failing_sql'])]
    corrected = [list(row) for row in db.execute('SELECT sku FROM stock WHERE qty > 0 ORDER BY sku')]
assert actual != case['expected_rows'] and corrected == case['expected_rows']
fields = {'setup':('setup','initialisation','création','seed'), 'failing_statement':('failing','statement','requête','instruction'), 'expected_rows':('expected','attendu','attendues'), 'private_terms':('quote','devis','private','privé','bespoke','sur mesure')}
lines = list(dict.fromkeys(line.strip() for item in strings(source) for line in item.splitlines() if line.strip()))
hits = {field:[line[:400] for line in lines if any(term in line.casefold() for term in terms)][:6] for field,terms in fields.items()}
report = {'source':str(p),'source_sha256':hashlib.sha256(raw).hexdigest(),'sqlite_version':sqlite3.sqlite_version,'fictional_plain_text_reply':'Setup SQL\n'+case['setup_sql']+'\n\nFailing statement\n'+case['failing_sql']+'\n\nConfirmed expected rows\n'+json.dumps(case['expected_rows'])+'\n\n'+case['qualification_question'],'actual_rows':actual,'corrected_control_rows':corrected,'intake_passages_for_manual_review':hits,'limits':'Keyword matches are pointers. Read both decoded prompts before asserting field coverage. This executes fictional SQL locally and establishes no mail delivery, buyer eligibility, quote approval or payment.'}
out = p.with_name('director-fictional-intake-rehearsal.json')
out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(json.loads(out.read_text(encoding='utf-8')),ensure_ascii=False))
